commit 510479ad88853d2e9649d5cad5863ef3b4e4d581
Author: Nick Hung <nick@andestech.com>
Date:   Sat Jul 25 07:39:28 2026 +0800

    ggml-cpu: Q1_0 weights-in-HVM redirect for the RISC-V repack path

    Behavioral change. At model load, the CPU repack buffer's set_tensor
    optionally redirects a Q1_0 repack tensor's storage into Andes HVM
    (high-bandwidth vector memory, CSR 0xFD1) *before* repacking, so the
    row-parallel gemv/gemm reads its per-column sign-plane stream from banked
    local memory instead of streaming from L3. Selected by tensor-name substring
    via the GGML_Q1_HVM env var or -DGGML_Q1_HVM_NAME; off by default, so no other
    build is affected. New hvm.h holds the pure bump allocator + name selector
    (host unit test in tests/test-hvm-place.cpp) and the target-only CSR window
    discovery. run-k51-hvm.sh drives the andesim fpga_l3 K=51 measurement.

    In-model K=51 (Bonsai-4B V-proj 2560x1024, fpga_l3): 2,144,755 -> 946,460
    cycles = 2.27x over the repack-in-RAM baseline (4.73x over pristine). Output
    verified bit-identical to the weights-in-RAM path.

    Co-Authored-By: Claude Opus 4.8 <noreply@anthropic.com>

diff --git a/ggml/src/ggml-cpu/repack.cpp b/ggml/src/ggml-cpu/repack.cpp
index 08b8827ff..0e0bbc9da 100644
--- a/ggml/src/ggml-cpu/repack.cpp
+++ b/ggml/src/ggml-cpu/repack.cpp
@@ -17,6 +17,9 @@
 #include <cstdio>  // for GGML_ASSERT

 #include "repack.h"
+#include "hvm.h"
+
+#include <cstdlib>  // getenv, for the Q1_0 weights-in-HVM redirect

 #if defined(__GNUC__)
 #pragma GCC diagnostic ignored "-Woverlength-strings"
@@ -4899,11 +4902,51 @@ static enum ggml_status ggml_backend_cpu_repack_buffer_init_tensor(ggml_backend_
     return GGML_STATUS_SUCCESS;
 }

+#if defined(__riscv)
+// Single per-process HVM bump allocator. repack set_tensor runs
+// single-threaded at model load, so the file-static window state is safe.
+// Window discovered once via CSR 0xFD1 (base) / 0xFD0 (log2 size).
+static void * ggml_hvm_alloc(size_t size, size_t align) {
+    static uint64_t off = 0, end = 0;
+    if (end == 0) {
+        off = ggml_hvm_csr_base();
+        end = off + (1ull << (ggml_hvm_csr_cfg() & 0xff));
+    }
+    return ggml_hvm_bump(&off, end, size, align);
+}
+#endif
+
 static void ggml_backend_cpu_repack_buffer_set_tensor(ggml_backend_buffer_t buffer, struct ggml_tensor * tensor,
                                                        const void * data, size_t offset, size_t size) {
     GGML_ASSERT(offset == 0);
     GGML_ASSERT(size == ggml_nbytes(tensor));

+#if defined(__riscv)
+    // weights-in-HVM (opt_roadmap F4): if this tensor's name matches the
+    // selector, redirect its storage into HVM *before* repacking, so the
+    // repack writes the interleaved sign-planes straight into HVM (no extra
+    // copy). Off unless GGML_Q1_HVM env var or -DGGML_Q1_HVM_NAME is set.
+    const char * hvm_sel = getenv("GGML_Q1_HVM");
+#  ifdef GGML_Q1_HVM_NAME
+    // stringify so an unquoted -DGGML_Q1_HVM_NAME=attn_v works (no cmake quote hell)
+#    define GGML_Q1_HVM_STR2(x) #x
+#    define GGML_Q1_HVM_STR(x)  GGML_Q1_HVM_STR2(x)
+    if (!hvm_sel || !hvm_sel[0]) {
+        hvm_sel = GGML_Q1_HVM_STR(GGML_Q1_HVM_NAME);
+    }
+#  endif
+    if (ggml_hvm_selected(tensor->name, hvm_sel)) {
+        void * p = ggml_hvm_alloc(ggml_nbytes(tensor), 64);
+        if (p) {
+            fprintf(stderr, "[q1-hvm] %s [%lld x %lld] -> HVM %p (%zu B)\n", tensor->name,
+                    (long long) tensor->ne[0], (long long) tensor->ne[1], p, ggml_nbytes(tensor));
+            tensor->data = p;
+        } else {
+            fprintf(stderr, "[q1-hvm] %s selected but HVM window full -- staying in RAM\n", tensor->name);
+        }
+    }
+#endif
+
     auto tensor_traits = (ggml::cpu::repack::tensor_traits_base *) tensor->extra;
     auto OK            = tensor_traits->repack(tensor, data, size);

