Author: Nick Hung <nick@andestech.com>
Date:   Fri Aug 7 14:57:04 2026 +0800

    fix(riscv): vec_dot f32/f16 - no _tu merge into uninitialized accumulators

    The tail-undisturbed accumulate merged into vector registers that were
    never initialized for the first stripe; seed them explicitly so the
    reduction is well-defined at every VLEN.

    Co-Authored-By: Claude Fable 5 <noreply@anthropic.com>

diff --git a/ggml/src/ggml-cpu/vec.cpp b/ggml/src/ggml-cpu/vec.cpp
index ff2b636df..7fa93dcf8 100644
--- a/ggml/src/ggml-cpu/vec.cpp
+++ b/ggml/src/ggml-cpu/vec.cpp
@@ -85,20 +85,22 @@ void ggml_vec_dot_f32(int n, float * GGML_RESTRICT s, size_t bs, const float * G
         // reduce sum1,sum2 to sum1
         GGML_F32_VEC_REDUCE(sumf, sum1, sum2, sum3, sum4, sum5, sum6, sum7, sum8);
     #elif defined(__riscv_v_intrinsic)
-        int vl = __riscv_vsetvlmax_e32m8();
-        vfloat32m1_t vs = __riscv_vfmv_v_f_f32m1(0.0f, 1);
-        vfloat32m8_t vsum;
-        vfloat32m8_t ax;
-        vfloat32m8_t ay;
-        vsum = __riscv_vfmv_v_f_f32m8_tu(vsum, 0.0f, vl);
-        for (int i = 0; i < n; i += vl) {
+        // The accumulator must be zeroed by a plain (non-_tu) init at vlmax:
+        // a _tu init merging into an uninitialized register is indeterminate,
+        // and GCC 14 re-materializes it under whatever vtype is current (seen
+        // as e8,m2,ta), leaving most of the m8 group tail-agnostic garbage.
+        // The loads need no _tu either; the _tu on the accumulate is what
+        // keeps the high-lane partial sums intact on the final short stripe.
+        const int vlmax = __riscv_vsetvlmax_e32m8();
+        vfloat32m8_t vsum = __riscv_vfmv_v_f_f32m8(0.0f, vlmax);
+        for (int i = 0, vl = 0; i < n; i += vl) {
             vl = __riscv_vsetvl_e32m8(n - i);
-            ax = __riscv_vle32_v_f32m8_tu(ax, &x[i], vl);
-            ay = __riscv_vle32_v_f32m8_tu(ay, &y[i], vl);
+            vfloat32m8_t ax = __riscv_vle32_v_f32m8(&x[i], vl);
+            vfloat32m8_t ay = __riscv_vle32_v_f32m8(&y[i], vl);
             vsum = __riscv_vfmacc_vv_f32m8_tu(vsum, ax, ay, vl);
         }
-        vl = __riscv_vsetvlmax_e32m8();
-        vs = __riscv_vfredusum_vs_f32m8_f32m1(vsum, vs, vl);
+        vfloat32m1_t vs = __riscv_vfmv_v_f_f32m1(0.0f, 1);
+        vs = __riscv_vfredusum_vs_f32m8_f32m1(vsum, vs, vlmax);
         sumf += __riscv_vfmv_f_s_f32m1_f32(vs);
     #else
         const int np = (n & ~(GGML_F32_STEP - 1));
@@ -320,21 +322,24 @@ void ggml_vec_dot_f16(int n, float * GGML_RESTRICT s, size_t bs, ggml_fp16_t * G
         sumf = ggml_sve_sum_f32x2(sum1_lo, sum1_hi);
     #elif defined(__riscv_v_intrinsic)
         #if defined(__riscv_zvfh)
-            int vl = __riscv_vsetvlmax_e32m2();
-            vfloat32m1_t vs = __riscv_vfmv_v_f_f32m1(0.0f, 1);
-            vfloat32m2_t vsum;
-            vfloat16m1_t ax;
-            vfloat16m1_t ay;
-            vsum = __riscv_vreinterpret_v_u32m2_f32m2(__riscv_vmv_v_x_u32m2(0, vl));

